// Reads audio/script.md — the phrases the phone says — and writes the clip identifiers the screens
// may ask for (apps/web/src/app/core/audio/script-clips.ts): an identifier missing from the script
// does not typecheck. `--check` only says whether the generated file is current.
//   node tools/audio-script.mjs           write the file
//   node tools/audio-script.mjs --check   exit 1 if the file is stale
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
export const SCRIPT = join(root, 'audio/script.md');
export const GENERATED = join(root, 'apps/web/src/app/core/audio/script-clips.ts');

/**
 * The identifiers of the script, from the first cell of each table row: `one-id`, a list
 * `a`, `b`, a run `deaths-today-1` … `-20`, or a stepped run `number-30`, `number-40`, … `number-90`.
 * Fixed clips are said as they are; a family is a phrase recorded once per number.
 */
export function scriptClips(text) {
  const fixed = [];
  const families = {};
  for (const line of text.split('\n')) {
    const cell = /^\| ([^|]*`[^|]*)\|/.exec(line)?.[1];
    if (cell === undefined) {
      continue;
    }
    const [left, right] = cell.split('…');
    const ids = [...left.matchAll(/`([a-z0-9-]+)`/g)].map((match) => match[1]);
    if (right === undefined) {
      fixed.push(...ids);
      continue;
    }
    const last = /`-?([a-z0-9-]*?)-?(\d+)`/.exec(right);
    const first = /^(.*)-(\d+)$/.exec(ids[0] ?? '');
    if (last === null || first === null) {
      throw new Error(`Unreadable run of clips: ${cell.trim()}`);
    }
    const family = first[1];
    const from = Number(first[2]);
    const step = ids.length > 1 ? Number(/-(\d+)$/.exec(ids[1])[1]) - from : 1;
    const numbers = (families[family] ??= []);
    for (let value = from; value <= Number(last[2]); value += step) {
      numbers.push(value);
    }
  }
  return { fixed: [...new Set(fixed)].sort(), families };
}

/** Every file name the script asks for. */
export function allClipIds({ fixed, families }) {
  return [...fixed, ...Object.entries(families).flatMap(([family, numbers]) => numbers.map((value) => `${family}-${value}`))].sort();
}

export function generated(clips) {
  const union = (values) => values.map((value) => `\n  | '${value}'`).join('');
  const counted = Object.keys(clips.families).filter((family) => family !== 'number').sort();
  return `// Generated by tools/audio-script.mjs from audio/script.md — do not edit: change the script, then run the tool.

/** A clip of the script said as it is, or a number or a unit of the annex. */
export type ScriptClip =${union(clips.fixed)};

/** A phrase recorded once per number (\`deaths-today-3\`): the whole phrase is said when it is recorded. */
export type CountedFamily =${union(counted)};
`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const content = generated(scriptClips(readFileSync(SCRIPT, 'utf8')));
  if (process.argv.includes('--check')) {
    const current = readFileSync(GENERATED, 'utf8');
    if (current !== content) {
      console.error('script-clips.ts is stale: run node tools/audio-script.mjs');
      process.exit(1);
    }
  } else {
    writeFileSync(GENERATED, content);
  }
}
